204	// rank returns the candidates that match query in the given mode, best first.
205	// It is pure: cands is neither reordered nor modified. Fuzzy ranks by Match
206	// score; exact puts a match at a path boundary first, then the shorter label,
207	// and ties keep the original order.
208	func rank(cands []Candidate, query string, mode Mode) []Candidate {
209		if mode == ModeExact {
210			type hit struct {
211				c        Candidate
212				boundary bool
213				length   int
214			}
215			hits := make([]hit, 0, len(cands))
216			for _, c := range cands {
217				if boundary, ok := MatchExact(c.Label, query); ok {
218					hits = append(hits, hit{c: c, boundary: boundary, length: utf8.RuneCountInString(c.Label)})
219				}
220			}
221			sort.SliceStable(hits, func(i, j int) bool {
222				if hits[i].boundary != hits[j].boundary {
223					return hits[i].boundary
224				}
225				return hits[i].length < hits[j].length
226			})
227			rows := make([]Candidate, len(hits))
228			for i, h := range hits {
229				rows[i] = h.c
230			}
231			return rows
232		}
233	
234		type scored struct {
235			c     Candidate
236			score int
237		}
238		matches := make([]scored, 0, len(cands))
239		for _, c := range cands {
240			if score, ok := Match(c.Label, query); ok {
241				matches = append(matches, scored{c: c, score: score})
242			}
243		}
244		sort.SliceStable(matches, func(i, j int) bool { return matches[i].score > matches[j].score })
245	
246		rows := make([]Candidate, len(matches))
247		for i, m := range matches {
248			rows[i] = m.c
249		}
250		return rows
251	}
