267	// MatchHint is the bar's inline count, the same role goto's "1-N" plays.
268	func (f *Finder) MatchHint() string {
269		query := strings.TrimSpace(f.query.Value())
270		if f.loading || len(query) < MinQueryLen {
271			return ""
