277	// the same components.BarFrame the "/" filter and the viewer's own "g" (go to
278	// line) already use, so the rectangle that closes the viewport is the same one
279	// whichever occupies it.
280	func (f *Finder) RenderBar(width int) string {
281		inner := theme.Bg(" ") + theme.KeyStyle.Render("Find") +
282			theme.Bg(" ") + theme.DimStyle.Render(f.mode.String()) +
283			theme.Bg(" ") + theme.DimStyle.Render(theme.IconChevronRight) + theme.Bg(" ") +
284			f.query.View()
285		if hint := f.MatchHint(); hint != "" {
286			inner += theme.Bg("  ") + theme.DimStyle.Render(hint)
287		}
288		return sharedcomponents.BarFrame(width, inner)
289	}
