291	// ModeShortcut is the entry the view adds to its header and help: tab, named
292	// after the mode it would switch to. It always applies, so it is never greyed.
293	func (f *Finder) ModeShortcut() shortcut.Shortcut {
294		if f.mode == ModeFuzzy {
295			return shortcut.Shortcut{Key: "tab", Description: "Exact match"}
296		}
297		return shortcut.Shortcut{Key: "tab", Description: "Fuzzy match"}
298	}
