301	// blank line, and the info line the view's own footer message renders with
302	// this prompt's status (Rule 128). Four lines — FooterHeight.
303	func (f *Finder) RenderFooter(width int, footer *sharedcomponents.FooterMessage) string {
304		info := footer.View(width, sharedcomponents.Status{Text: f.StatusText()})
305		return f.RenderBar(width) + "\n" + theme.EmptyLineBg(width) + "\n" + info
306	}
