	}
	for i, w := range want {
		if i > 0 {
			f = press(t, f, "tab")
		}
		got := f.ModeShortcut()
		if got.Key != w.Key || got.Description != w.Description {
			t.Errorf("after %d tab(s) ModeShortcut() = {%q %q}, want {%q %q}",
				i, got.Key, got.Description, w.Key, w.Description)
		}
		if got.Disabled {
